create table if not exists public.profile (id int primary key default 1, name text not null default '', location text not null default '', description text not null default '', photo text not null default '', vk text not null default '', telegram text not null default '', chat text not null default '', constraint one_row check (id = 1));
create table if not exists public.events (id bigint primary key, type text not null, title text not null default '', text text not null default '', author text not null default '', date timestamptz not null default now(), demo boolean not null default false);
create table if not exists public.posts (id bigint primary key, title text not null default '', text text not null default '', author text not null default '', image text not null default '', date timestamptz not null default now(), demo boolean not null default false);
create table if not exists public.transactions (id bigint primary key, kind text not null check (kind in ('income','expense')), amount numeric not null default 0, title text not null default '', date timestamptz not null default now(), demo boolean not null default false);
alter table public.profile enable row level security;
alter table public.events enable row level security;
alter table public.posts enable row level security;
alter table public.transactions enable row level security;
drop policy if exists "open profile" on public.profile;
create policy "open profile" on public.profile for all using (true) with check (true);
drop policy if exists "open events" on public.events;
create policy "open events" on public.events for all using (true) with check (true);
drop policy if exists "open posts" on public.posts;
create policy "open posts" on public.posts for all using (true) with check (true);
drop policy if exists "open transactions" on public.transactions;
create policy "open transactions" on public.transactions for all using (true) with check (true);
alter table public.profile replica identity full;
alter table public.events replica identity full;
alter table public.posts replica identity full;
alter table public.transactions replica identity full;
do $$ begin alter publication supabase_realtime add table public.profile, public.events, public.posts, public.transactions; exception when duplicate_object then null; end $$;
insert into storage.buckets (id, name, public) values ('photos','photos',true) on conflict (id) do update set public = true;
drop policy if exists "photos read" on storage.objects;
create policy "photos read" on storage.objects for select using (bucket_id = 'photos');
drop policy if exists "photos write" on storage.objects;
create policy "photos write" on storage.objects for insert with check (bucket_id = 'photos');
drop policy if exists "photos update" on storage.objects;
create policy "photos update" on storage.objects for update using (bucket_id = 'photos');
drop policy if exists "photos delete" on storage.objects;
create policy "photos delete" on storage.objects for delete using (bucket_id = 'photos');